def prepare_ui_node(node: dict, explicit: dict | None = None) -> dict:
    """Encode explicitly supplied layout fields for Unity JsonUtility."""
    explicit = node if explicit is None else explicit
    result = dict(node)
    for key in ('width', 'height', 'x', 'y', 'anchor', 'offset_min', 'offset_max', 'raycast_target'):
        present = explicit.get(key) is not None
        result["has_" + key] = present
        if node.get(key) is None:
            result.pop(key, None)
    children = explicit.get("children", [])
    result["children"] = [prepare_ui_node(child, children[i] if i < len(children) else {})
                          for i, child in enumerate(node.get("children", []))]
    return result
